type PromiseRoutes<Routes> = {
  [Key in keyof Routes]: Routes[Key] extends (
    ...args: infer Arguments
  ) => Effect.Effect<infer Result, unknown, HttpClient.HttpClient>
    ? (...args: Arguments) => Promise<Result>
    : never;
};

/** Promise adapter for the generated station routes. */
export function createStationApi(
  stationUrl: string | URL,
  mediaUrl: string | URL,
  signal?: AbortSignal,
) {
  const routes = createStationEffectApi(stationUrl, mediaUrl);
  return Object.fromEntries(
    Object.entries(routes).map(([name, route]) => [
      name,
      async (...args: unknown[]) =>
        runStationEffect(
          (
            route as (
              ...args: unknown[]
            ) => Effect.Effect<unknown, unknown, HttpClient.HttpClient>
          )(...args),
          signal,
        ),
    ]),
  ) as PromiseRoutes<typeof routes>;
}
